  app.post<{ Params: { chatId: string } }>(
    "/api/tasks/:chatId/retry",
    async (request, reply) => {
      const plainInput = taskOperationStartSchema.safeParse(request.body);
      const encryptedInput = taskEncryptedOperationStartSchema.safeParse(
        request.body,
      );
      let input: TaskOperationStart;
      let legacyOperationKind:
        TaskOperationRelayRequest["classification"]["kind"] | null = null;
      if (plainInput.success) {
        input = plainInput.data;
      } else if (encryptedInput.success) {
        input = {
          operationId: encryptedInput.data.operation.operationId,
          rowVersion: encryptedInput.data.rowVersion,
        };
        legacyOperationKind = encryptedInput.data.operation.classification.kind;
      } else {
        return reply.code(400).send(invalidBody(plainInput.error.issues));
      }
      const context = await repository.getChatExecutionContext(
        applicationOwnerId(),
        request.params.chatId,
      );
      if (!context || context.experience !== "task") {
        return reply.code(404).send({ error: "Task not found." });
      }
      const task = await repository.tasks.get(
        applicationOwnerId(),
        request.params.chatId,
      );
      if (
        task?.state === "implementing" &&
        task.hasFinalPlan &&
        task.hasGoalPrompt
      ) {
        return reply.code(202).send(taskOpaqueSummarySchema.parse(task));
      }
      if (task?.state !== "failed" || !task.lastError) {
        return reply
          .code(409)
          .send({ error: "This Task has no failed operation to retry." });
      }
      try {
        if (task.lastError.operationKind === "finalize") {
          const rounds = await repository.tasks.listRounds(
            applicationOwnerId(),
            request.params.chatId,
          );
          const latest = rounds.find(
            (round) => round.ordinal === task.planningRound,
          );
          const prepared = latest
            ? await repository.tasks.getOperationContext(
                applicationOwnerId(),
                request.params.chatId,
                { operationId: latest.id },
              )
            : null;
          if (prepared?.relayResult?.goal) {
            const retried = await queueTaskOperation(
              request.params.chatId,
              { operationId: latest.id, rowVersion: input.rowVersion },
              "finalize",
            );
            return retried
              ? reply.code(202).send(taskOpaqueSummarySchema.parse(retried))
              : reply.code(404).send({ error: "Task not found." });
          }
        }
        if (task.lastError.operationKind === "implementation") {
          return reply.code(409).send({
            error:
              "Use the implementation Goal controls to resume or restart this Task.",
          });
        }
        if (
          legacyOperationKind !== null &&
          legacyOperationKind !== task.lastError.operationKind
        ) {
          return reply.code(409).send({
            error: "The encrypted retry does not match the failed operation.",
          });
        }
        const retried = await queueTaskOperation(
          request.params.chatId,
          input,
          task.lastError.operationKind,
        );
        return retried
          ? reply.code(202).send(taskOpaqueSummarySchema.parse(retried))
          : reply.code(404).send({ error: "Task not found." });
      } catch (error) {
        const response = taskMutationError(error, reply);
        if (response) return response;
        return sendWorkerRequestFailure(reply, error);
      }
    },
  );

  app.post<{ Params: { chatId: string } }>(
    "/api/chats/:chatId/console",
    async (request, reply) => {
      const input = encryptedLinkedConsoleCreateSchema.safeParse(request.body);
      if (!input.success) {
        return reply.code(400).send(invalidBody(input.error.issues));
      }
      let context = await repository.getChatExecutionContext(
        applicationOwnerId(),
        request.params.chatId,
      );
      if (!context) {
        return reply.code(404).send({ error: "Chat source not found." });
      }
      if (context.experience === "task") {
        return reply.code(409).send({
          error: "Encrypted Task console state stays on its authorized worker.",
        });
      }
      const modelId = await resolveModelId(context);
      const runtime = await runtimeForContext(context);
      if (!runtime) {
        return reply
          .code(409)
          .send({ error: "No provider route is currently available." });
      }
      if (!context.threadId || !runtimeCanResumeContext(context, runtime)) {
        if (!bridge.isConnected(context.workerId)) {
          return reply.code(503).send({ error: "Project worker is offline." });
        }
        try {
          const mcpServers = await repository.listEffectiveMcpServers(
            applicationOwnerId(),
            context.projectId,
            context.workerId,
          );
          const result = (await bridge.request(context.workerId, {
            type: "chat.thread.ensure",
            cwd: context.cwd,
            threadId: null,
            planMode: context.planMode,
            model: runtime.model,
            provider: runtime.provider,
            permissionProfileId:
              effectivePermissionProfile(context).effectiveId,
            mcpServers,
          })) as { threadId?: unknown };
          if (typeof result.threadId !== "string" || !result.threadId) {
            throw new Error("Codex did not return a console thread.");
          }
          await repository.setChatModel(applicationOwnerId(), context.chatId, {
            modelId,
          });
          await repository.updateChatRuntime(
            context.chatId,
            context.workerId,
            context.worktreeId,
            result.threadId,
            runtime.routeId,
            "ready",
            runtime.provider.accountId,
          );
          const updated = await repository.getChatExecutionContext(
            applicationOwnerId(),
            context.chatId,
          );
          if (!updated) throw new Error("Chat source not found.");
          context = updated;
        } catch (error) {
          return sendWorkerConflictFailure(reply, error);
        }
      }
      const terminal = await repository.getOrCreateChatConsole(
        applicationOwnerId(),
        context.chatId,
        input.data,
      );
      return terminal
        ? reply.code(201).send(terminalWireSummarySchema.parse(terminal))
        : reply.code(404).send({ error: "Chat source not found." });
    },
  );

